  flex-direction: column;
  background-color: rgba(255, 255, 255, 0.05);
  border-radius: 0.5rem;
  padding: 1.5rem;
}

.search-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.search-input-group {
  position: relative;
  flex: 1;
}

.search-input {
  width: 100%;
  padding: 0.75rem;
  padding-right: 2.5rem;
  background-color: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 0.375rem;
  color: #f3f4f6;
  font-size: 1rem;
  transition: border-color 0.2s, background-color 0.2s;
}

.search-input::placeholder {
  color: rgba(243, 244, 246, 0.5);
}

.search-input:focus {
  outline: none;
  border-color: #9333ea;
  background-color: rgba(255, 255, 255, 0.15);
}

.search-input:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.clear-btn {
  position: absolute;
  right: 0.5rem;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: #f3f4f6;
  font-size: 1.5rem;
  cursor: pointer;
  padding: 0.25rem 0.5rem;
  line-height: 1;
  opacity: 0.6;
  transition: opacity 0.2s;
}

.clear-btn:hover {
  opacity: 1;
}

.search-btn {
  padding: 0.75rem 1.5rem;
  background-color: #9333ea;
  color: white;
  border: none;
  border-radius: 0.375rem;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.2s;
  white-space: nowrap;
}

.search-btn:hover:not(:disabled) {
  background-color: #7e22ce;
}

.search-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.error-message {
  padding: 0.75rem;
  background-color: rgba(239, 68, 68, 0.2);
  border: 1px solid rgba(239, 68, 68, 0.4);
  border-radius: 0.375rem;
  color: #fca5a5;
  margin-bottom: 1rem;
  font-size: 0.875rem;
}

.results-container {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.loading-spinner {
  text-align: center;
  padding: 2rem;
  color: #9333ea;
  font-size: 1rem;
}

.placeholder-message,
.no-results-message {
  text-align: center;
  padding: 2rem;
  color: rgba(243, 244, 246, 0.6);
  font-size: 0.875rem;
}

.results-list {
  list-style: none;
  padding: 0;
  margin: 0;
  flex: 1;
}

.result-item {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  cursor: pointer;
  transition: background-color 0.2s;
  text-transform: capitalize;
  color: #f3f4f6;
}

.result-item:hover {
